xql_query:
// ============================================================
// Rule: WIN_Domain Reconnaissance via Net Command Burst
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_Domain Reconnaissance via Net Command Burst.
// Severity: SEV_030_MEDIUM
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0007 - Discovery
// Technique: T1087.002 - Account Discovery: Domain Account
// Technique: T1069.002 - Permission Groups Discovery: Domain Groups
// Technique: T1018 - Remote System Discovery
// Technique: T1201 - Password Policy Discovery

config case_sensitive = false

| dataset = xdr_data

| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.PROCESS
| filter event_sub_type = ENUM.PROCESS_START

| alter
    process_name_lc = lowercase(action_process_image_name),
    process_command_line_lc = lowercase(action_process_image_command_line)

| filter process_name_lc in ("net.exe", "net1.exe")

// Domain-scoped discovery subcommands
| filter process_command_line_lc ~= ".*\\s(user|group|localgroup|computer|session|view|accounts)(\\s|$).*"
| filter process_command_line_lc ~= ".*(/domain|\\sdomain(\\s|$)).*"

// The correlation rule search window supplies the temporal boundary
| comp
    count() as command_count,
    count_distinct(action_process_image_command_line) as distinct_command_count,
    min(_time) as first_seen,
    max(_time) as last_seen,
    values(action_process_image_name) as discovery_processes,
    values(action_process_image_path) as discovery_paths,
    values(action_process_image_command_line) as discovery_commands,
    values(actor_process_image_name) as parent_processes,
    values(actor_process_command_line) as parent_commands
  by agent_hostname, agent_id, actor_effective_username

// Avoid alerting on a single administrative query
| filter command_count >= 3 and distinct_command_count >= 3

| fields
    first_seen,
    last_seen,
    command_count,
    distinct_command_count,
    agent_hostname,
    agent_id,
    actor_effective_username,
    discovery_processes,
    discovery_paths,
    discovery_commands,
    parent_processes,
    parent_commands
